def f(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    # connected components of 3s
    comps=[]; seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]==3 and not seen[i][j]:
                st=[(i,j)]; comp=[]; seen[i][j]=True
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and g[na][nb]==3 and not seen[na][nb]:
                            seen[na][nb]=True; st.append((na,nb))
                comps.append(comp)
    anchors=set()
    for ci,comp in enumerate(comps):
        threes=comp
        r0=min(a for a,b in threes); r1=max(a for a,b in threes)
        c0=min(b for a,b in threes); c1=max(b for a,b in threes)
        # which 2s lie within this comp's bbox
        twos=[]
        for i in range(h):
            for j in range(w):
                if g[i][j]==2 and r0<=i<=r1 and c0<=j<=c1:
                    # count 2-neighbors inside this comp's bbox
                    n2=sum(1 for a in range(i-1,i+2) for b in range(j-1,j+2)
                           if (a,b)!=(i,j) and r0<=a<=r1 and c0<=b<=c1 and g[a][b]==2)
                    twos.append((n2,i,j))
        # keep the 2s with max count as anchors?
        mx=max(n2 for n2,i,j in twos)
        anchors|={(i,j) for n2,i,j in twos if n2==mx}
    # now: for each comp, anchor = 2 with most 2 neighbors; if ties... just take all tied.
    # but demo shows TWO tied 2s at (16,10),(17,11) stay 2 — matches anchors staying
    for i in range(h):
        for j in range(w):
            if g[i][j]==2 and (i,j) in anchors: continue
            if (i,j) not in anchors: continue
            for a in range(i-1,i+2):
                for b in range(j-1,j+2):
                    if 0<=a<h and 0<=b<w and (a,b)!=(i,j):
                        out[a][b]=1
    return out
